constraints:
1 ≤ |S| ≤ 10^{5}
1 ≤ X,Y ≤ 10^{5}
S contains lowercase English letters only.

expected time complexity: O(|S|)
expected auxiliary space: O(|S|)

standard_solution_code:
class Solution:

	def solve(self, X, Y, S):

		def find(st, cost, stri):
			stac = ['$']
			ans = 0
			for i in stri:
				stac.append(i)
				if stac[-2] == st[0] and stac[-1] == st[1]:
					stac.pop()
					stac.pop()
					ans += cost
			return (ans, ''.join(stac[1:]))
		if X > Y:
			(gain, st) = find('pr', X, S)
			(c, _) = find('rp', Y, st)
			return gain + c
		else:
			(gain, st) = find('rp', Y, S)
			(c, _) = find('pr', X, st)
			return gain + c
